import java.io.*;
import java.util.*;

public class Main {
    static class Line {
        long v1, v2;
        int rank;
        Line(long v1, long v2) {
            this.v1 = v1;
            this.v2 = v2;
        }
    }

    static class Fenwick {
        int[] bit;
        int n;

        Fenwick(int n) {
            this.n = n;
            bit = new int[n + 1];
        }

        void add(int idx, int val) {
            for (; idx <= n; idx += idx & -idx) {
                bit[idx] += val;
            }
        }

        int sum(int idx) {
            int s = 0;
            for (; idx > 0; idx -= idx & -idx) {
                s += bit[idx];
            }
            return s;
        }
    }

    static int lowerBound(long[] arr, int len, long key) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < key) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        long X1 = Long.parseLong(st.nextToken());
        long X2 = Long.parseLong(st.nextToken());

        Line[] lines = new Line[N];
        long[] v2s = new long[N];

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            long A = Long.parseLong(st.nextToken());
            long B = Long.parseLong(st.nextToken());

            long v1 = A * X1 + B;
            long v2 = A * X2 + B;

            lines[i] = new Line(v1, v2);
            v2s[i] = v2;
        }

        Arrays.sort(lines, (a, b) -> Long.compare(a.v1, b.v1));
        Arrays.sort(v2s);

        int m = 0;
        for (int i = 0; i < N; i++) {
            if (i == 0 || v2s[i] != v2s[m - 1]) {
                v2s[m++] = v2s[i];
            }
        }

        for (Line line : lines) {
            line.rank = lowerBound(v2s, m, line.v2) + 1;
        }

        Fenwick fw = new Fenwick(m);
        long ans = 0;

        int i = 0;
        while (i < N) {
            int j = i;
            while (j < N && lines[j].v1 == lines[i].v1) {
                j++;
            }

            int groupSize = j - i;
            ans += (long) groupSize * (groupSize - 1) / 2;

            int totalPrev = fw.sum(m);
            for (int k = i; k < j; k++) {
                int less = fw.sum(lines[k].rank - 1);
                ans += totalPrev - less;
            }

            for (int k = i; k < j; k++) {
                fw.add(lines[k].rank, 1);
            }

            i = j;
        }

        System.out.println(ans);
    }
}
